const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const STORAGE='kadro-arena-v1';
const VERSION_STORAGE='erkekler-shared-version-v1';
const SYNC_INTERVAL=3000;
const statsMeta={pace:'Hız',shoot:'Şut',pass:'Pas',dribble:'Dripling',defense:'Defans',physical:'Fizik',stamina:'Stamina',reflex:'Refleks',save:'Kurtarış',positioning:'Pozisyon',distribution:'Dağıtma'};
const fieldKeys=['pace','shoot','pass','dribble','defense','physical','stamina'];
const keeperKeys=['reflex','save','positioning','distribution'];
const formations={6:['2-2-1','1-3-1'],7:['2-3-1','3-2-1'],8:['3-3-1','2-3-2']};
const colors=['#d9a45a','#7d9d86','#9c6bd6','#d67862','#608fc7','#6aa382','#d8c269','#b86c79'];

function avatar(name,color='#c59d55'){
  const initials=name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 180 210"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="${color}"/><stop offset="1" stop-color="#17251f"/></linearGradient></defs><rect width="180" height="210" fill="url(#g)"/><circle cx="90" cy="70" r="41" fill="#e1b38d"/><path d="M48 67q4-50 43-50 39 3 42 52-15-24-42-23T48 67" fill="#18211d"/><path d="M25 210q8-83 65-83t65 83" fill="#14251e"/><text x="90" y="187" text-anchor="middle" font-family="Arial" font-weight="700" font-size="25" fill="#d9ff65">${initials}</text></svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}
function seedPlayer(name,nick,pos,alt,base,i){
  const bump=(n)=>Math.max(50,Math.min(94,base+n));
  const stats={pace:bump((i*3)%11-4),shoot:bump((i*5)%13-8),pass:bump((i*7)%12-5),dribble:bump((i*2)%10-3),defense:bump((i*4)%17-9),physical:bump((i*6)%12-5),stamina:bump((i*8)%10-4),reflex:bump(4),save:bump(1),positioning:bump(2),distribution:bump(-2)};
  return {id:crypto.randomUUID(),name,nick,pos,alt,stats,photo:avatar(name,colors[i%colors.length]),photoX:50,photoY:50,photoScale:110};
}
function createInitial(){
  const raw=[['Emir Karaca','EMİR','FV','OS',85],['Berk Kaya','BERK','OS','FV',80],['Mert Yılmaz','MERT','DF','OS',82],['Can Demir','CAN','KL','',84],['Arda Şen','ARDA','DF','OS',77],['Ozan Çelik','OZAN','OS','DF',78],['Kerem Aydın','KEREM','FV','OS',83],['Efe Doğan','EFE','DF','',75],['Tolga Akın','TOLGA','KL','DF',76],['Batuhan Koç','BATU','OS','FV',81],['Serkan Güneş','SERKAN','DF','OS',79],['Umut Öz','UMUT','FV','',74],['Kaan Işık','KAAN','OS','DF',77],['Burak Eren','BURAK','DF','',73],['Ali Tunç','ALİ','FV','OS',79],['Cem Polat','CEM','OS','',72]];
  const players=raw.map((p,i)=>seedPlayer(...p,i));
  const date=new Date(); date.setDate(date.getDate()+((3-date.getDay()+7)%7));
  const match={id:crypto.randomUUID(),name:'Çarşamba Halı Saha',date:date.toISOString().slice(0,10),format:6,formationA:'2-2-1',formationB:'2-2-1',bench:players.slice(0,12).map(p=>p.id),out:players.slice(12).map(p=>p.id),teamA:{},teamB:{},locked:[]};
  return {players,matches:[match],activeMatchId:match.id,poolTab:'bench'};
}
function normalizeState(value){
  const next=value&&Array.isArray(value.players)&&Array.isArray(value.matches)?value:createInitial();
  next.history=Array.isArray(next.history)?next.history:[];next.poolTab=next.poolTab||'bench';return next;
}
let state; try{state=normalizeState(JSON.parse(localStorage.getItem(STORAGE)))}catch{state=createInitial()}
let cloudVersion=Number(localStorage.getItem(VERSION_STORAGE)||0),syncReady=false,syncing=false,dirty=false,localRevision=0,syncTimer=null,pollTimer=null,initRunning=false;
let selectedPlayer=null,editingPlayer=null,pendingPhoto=null;
const match=()=>state.matches.find(m=>m.id===state.activeMatchId)||state.matches[0];
const player=id=>state.players.find(p=>p.id===id);
const overall=p=>{
  const s=p.stats;
  const weights={DF:{defense:.30,physical:.22,pace:.13,pass:.12,stamina:.10,dribble:.08,shoot:.05},OS:{pass:.27,stamina:.20,dribble:.16,pace:.12,shoot:.10,physical:.08,defense:.07},FV:{shoot:.30,pace:.20,dribble:.15,physical:.10,pass:.10,stamina:.10,defense:.05}};
  if(p.pos==='KL')return Math.round(s.reflex*.32+s.save*.28+s.positioning*.22+s.distribution*.18);
  return Math.round(Object.entries(weights[p.pos]).reduce((a,[k,w])=>a+s[k]*w,0));
};
function persistLocal(){localStorage.setItem(STORAGE,JSON.stringify(state));localStorage.setItem(VERSION_STORAGE,String(cloudVersion))}
function save(){persistLocal();dirty=true;localRevision++;if(syncReady)scheduleSync()}
function setSyncStatus(status,label){const el=$('#syncStatus');if(!el)return;el.dataset.state=status;el.querySelector('span').textContent=label;el.title=status==='online'?'Tüm kullanıcılarla ortak veri bağlı':status==='syncing'?'Değişiklikler kaydediliyor':status==='offline'?'Ortak veri çevrimdışı; değişiklikler bu cihazda bekliyor':'Ortak veriye bağlanıyor'}
function renderCurrent(){renderSquad();if($('#playersView').classList.contains('active'))renderPlayers();if($('#matchesView').classList.contains('active'))renderMatches();renderHistory()}
function applyRemote(remote,version,{conflict=false}={}){state=normalizeState(remote);cloudVersion=version;dirty=false;localRevision++;persistLocal();if($('#playerDialog').open)$('#playerDialog').close();renderCurrent();if(conflict)notify('Başka bir cihaz daha önce güncelledi. En yeni ortak veri yüklendi; işlemi tekrar yapabilirsiniz.')}
function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(pushSharedState,220)}
async function pushSharedState(){
  if(!syncReady||!dirty)return;if(syncing){scheduleSync();return}syncing=true;setSyncStatus('syncing','Kaydediliyor');const revision=localRevision;
  try{const response=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state,baseVersion:cloudVersion})});const data=await response.json();
    if(response.status===409){applyRemote(data.state,data.version,{conflict:true});return}
    if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);cloudVersion=data.version;if(localRevision===revision)dirty=false;persistLocal();setSyncStatus('online','Ortak veri');
  }catch(error){console.error('Shared state sync failed',error);syncReady=false;setSyncStatus('offline','Yerel mod');if(String(error.message).includes('state_too_large'))notify('Ortak veri boyutu çok büyük. Büyük oyuncu fotoğraflarını yeniden yükleyin.');if(!initRunning)setTimeout(initSharedState,10000)}
  finally{syncing=false;if(dirty&&syncReady)scheduleSync()}
}
async function pollSharedState(){
  if(!syncReady||syncing||dirty)return;
  try{const response=await fetch('/api/state',{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();if(data.state&&data.version>cloudVersion)applyRemote(data.state,data.version);setSyncStatus('online','Ortak veri')}
  catch(error){console.error('Shared state poll failed',error);setSyncStatus('offline','Yerel mod')}
}
async function initSharedState(){
  if(initRunning)return;initRunning=true;setSyncStatus('connecting','Bağlanıyor');
  try{const response=await fetch('/api/state',{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);syncReady=true;
    if(data.state)applyRemote(data.state,data.version);else{cloudVersion=0;dirty=true;await pushSharedState();if(!syncReady)throw new Error('initial_write_failed')}
    clearInterval(pollTimer);pollTimer=setInterval(pollSharedState,SYNC_INTERVAL);setSyncStatus('online','Ortak veri');
  }catch(error){console.error('Shared state unavailable',error);syncReady=false;setSyncStatus('offline','Yerel mod');setTimeout(initSharedState,10000)}finally{initRunning=false}
}
function logEvent(type,text,detail=''){
  state.history.unshift({id:crypto.randomUUID(),type,text,detail,time:new Date().toISOString()});state.history=state.history.slice(0,100);save();renderHistory();
}
function renderHistory(){
  const list=$('#activityList'),icons={player:'♙',formation:'⌗',team:'⚡',move:'↔',match:'◷',lock:'▣'};if(!list)return;
  $('#activityCount').textContent=Math.min(state.history.length,99);list.innerHTML='';
  if(!state.history.length){list.innerHTML='<div class="activity-empty"><div><span>↺</span><b>Henüz işlem yok</b><p>Oyuncu ve kadro değişiklikleri burada görünecek.</p></div></div>';return}
  state.history.forEach(item=>{const date=new Date(item.time),el=document.createElement('article');el.className='activity-item';el.innerHTML=`<span class="activity-item-icon">${icons[item.type]||'•'}</span><div><strong>${item.text}</strong>${item.detail?`<p>${item.detail}</p>`:''}<time>${date.toLocaleDateString('tr-TR',{day:'numeric',month:'short'})} · ${date.toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}</time></div>`;list.append(el)})
}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._x);t._x=setTimeout(()=>t.classList.remove('show'),2400)}
function formatDate(d){return new Intl.DateTimeFormat('tr-TR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(d+'T12:00:00'))}
function playerCard(p,{lock=false,compact=true,role=''}={}){
  const o=overall(p),mismatch=role&&role!=='KL'&&p.pos==='KL'||role==='KL'&&p.pos!=='KL';
  const el=document.createElement('div');el.className=`mini-card${selectedPlayer===p.id?' selected':''}${mismatch?' mismatch':''}`;el.draggable=true;el.dataset.player=p.id;el.tabIndex=0;el.setAttribute('aria-label',`${p.nick}, ${o} overall, ${p.pos}`);
  el.innerHTML=`<span class="ovr">${o}</span><span class="pos">${p.pos}</span><div class="photo"><img alt="" src="${p.photo||avatar(p.name)}" style="object-position:${p.photoX??50}% ${p.photoY??50}%;transform:scale(${(p.photoScale||110)/100})"></div><span class="name">${p.nick}</span><span class="tiny-stats"><i>${p.stats.pace} HIZ</i><i>${p.stats.shoot} ŞUT</i><i>${p.stats.pass} PAS</i></span>${lock?`<button class="lock" title="Kilidi aç">▣</button>`:''}`;
  el.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/player',p.id);el.classList.add('dragging')});el.addEventListener('dragend',()=>el.classList.remove('dragging'));
  el.addEventListener('click',e=>{if(e.target.closest('.lock')){toggleLock(p.id);return} selectedPlayer=selectedPlayer===p.id?null:p.id;renderSquad()});
  el.addEventListener('dblclick',()=>openPlayer(p.id));
  return el;
}
function formationSlots(form){
  const rows=form.split('-').map(Number),slots=[{id:'GK',role:'KL',x:8,y:50}];
  rows.forEach((count,row)=>{const x=28+row*(62/Math.max(1,rows.length-1));for(let i=0;i<count;i++){const role=row===0?'DF':row===rows.length-1?'FV':'OS';slots.push({id:`${role}-${row}-${i}`,role,x,y:(i+1)*100/(count+1)})}});return slots;
}
function renderPitch(teamKey,form){
  const m=match(),box=$(`#slots${teamKey}`),team=m[`team${teamKey}`],slots=formationSlots(form);box.innerHTML='';
  slots.forEach(s=>{const el=document.createElement('div');el.className='slot';el.dataset.slot=s.id;el.dataset.team=teamKey;el.dataset.role=s.role;el.style.left=s.x+'%';el.style.top=s.y+'%';el.setAttribute('data-role',s.role);el.setAttribute('aria-label',`${teamKey} takımı ${s.role} slotu`);wireDrop(el,id=>moveToSlot(id,teamKey,s.id));
    if(team[s.id])el.append(playerCard(player(team[s.id]),{lock:m.locked.includes(team[s.id]),role:s.role}));
    el.addEventListener('click',e=>{if(e.target.closest('.mini-card'))return;if(selectedPlayer){moveToSlot(selectedPlayer,teamKey,s.id);selectedPlayer=null}});box.append(el)});
}
function wireDrop(el,action){el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drag-over')});el.addEventListener('dragleave',()=>el.classList.remove('drag-over'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drag-over');const id=e.dataTransfer.getData('text/player');if(id)action(id)})}
function locate(id){const m=match();for(const t of ['A','B'])for(const [slot,pid] of Object.entries(m[`team${t}`]))if(pid===id)return{type:'slot',team:t,slot};if(m.bench.includes(id))return{type:'bench'};if(m.out.includes(id))return{type:'out'};return null}
function detach(id){const m=match();m.bench=m.bench.filter(x=>x!==id);m.out=m.out.filter(x=>x!==id);for(const t of ['A','B'])for(const [slot,pid] of Object.entries(m[`team${t}`]))if(pid===id)delete m[`team${t}`][slot]}
function moveToSlot(id,teamKey,slot){const m=match(),dest=m[`team${teamKey}`],source=locate(id),occupant=dest[slot];if(occupant===id)return;if(occupant&&m.locked.includes(occupant)){notify('Bu oyuncu kilitli. Önce kilidi aç.');return}detach(id);if(occupant){delete dest[slot];if(source?.type==='slot')m[`team${source.team}`][source.slot]=occupant;else m.bench.push(occupant)}dest[slot]=id;logEvent('move',`${player(id).nick}, Takım ${teamKey} kadrosuna alındı`,`${slot.replaceAll('-',' ')} slotu${occupant?` · ${player(occupant).nick} ile yer değiştirdi`:''}`);renderSquad();const role=formationSlots(teamKey==='A'?m.formationA:m.formationB).find(x=>x.id===slot)?.role;if(role&&player(id).pos!==role&&!player(id).alt.split(',').map(x=>x.trim()).includes(role))notify(`${player(id).nick} için ${role} ikincil mevki değil; yine de yerleştirildi.`)}
function moveToZone(id,zone){const m=match();if(m.locked.includes(id)){notify('Kilitli oyuncuyu önce açmalısın.');return}detach(id);m[zone].push(id);logEvent('move',`${player(id).nick}, ${zone==='out'?'kadro dışına':'oyuncu havuzuna'} taşındı`,match().name);renderSquad()}
function toggleLock(id){const m=match();m.locked=m.locked.includes(id)?m.locked.filter(x=>x!==id):[...m.locked,id];logEvent('lock',`${player(id).nick} ${m.locked.includes(id)?'kilitlendi':'kilidi açıldı'}`,match().name);renderSquad();notify(m.locked.includes(id)?'Oyuncu yerinde kilitlendi.':'Oyuncu kilidi açıldı.')}
function teamMetrics(team){const ids=Object.values(team),sum=ids.reduce((a,id)=>a+overall(player(id)),0);return{count:ids.length,sum,avg:ids.length?sum/ids.length:0}}
function renderSummary(){const m=match(),a=teamMetrics(m.teamA),b=teamMetrics(m.teamB),diff=Math.abs(a.sum-b.sum);$('#teamsSummary').innerHTML=`<div class="summary-side a"><span class="letter">A</span><div class="summary-stat"><b>${a.count}/${m.format}</b><small>OYUNCU</small></div><div class="summary-stat"><b>${a.sum}</b><small>TOPLAM OVR</small></div><div class="summary-stat"><b>${a.avg.toFixed(1)}</b><small>ORTALAMA</small></div></div><div class="power-diff"><b>${diff}</b><small>GÜÇ FARKI</small></div><div class="summary-side b"><div class="summary-stat"><b>${b.avg.toFixed(1)}</b><small>ORTALAMA</small></div><div class="summary-stat"><b>${b.sum}</b><small>TOPLAM OVR</small></div><div class="summary-stat"><b>${b.count}/${m.format}</b><small>OYUNCU</small></div><span class="letter">B</span></div>`;$('#teamMiniA').innerHTML=`<b>${a.sum}</b> güç · ${a.avg.toFixed(1)} ort.`;$('#teamMiniB').innerHTML=`<b>${b.sum}</b> güç · ${b.avg.toFixed(1)} ort.`}
function renderPool(){const m=match(),tab=state.poolTab||'bench';$$('#poolTabs button').forEach(b=>b.classList.toggle('active',b.dataset.pool===tab));$('#poolDrop').dataset.zone=tab==='all'?'bench':tab;const ids=tab==='all'?state.players.map(p=>p.id):m[tab];const box=$('#poolCards');box.innerHTML='';ids.forEach(id=>box.append(playerCard(player(id),{lock:m.locked.includes(id)})));if(!ids.length)box.innerHTML=`<div class="empty-state"><div><b>Bu alan şu an boş</b>Kartları buraya sürükleyebilirsiniz.</div></div>`;$('#benchCount').textContent=m.bench.length;$('#outCount').textContent=m.out.length;$('#allCount').textContent=state.players.length}
function renderSquad(){const m=match();$('#matchTitle').textContent=m.name;$('#matchDateLabel').textContent=formatDate(m.date);$('#formatSelect').value=m.format;fillFormations();renderPitch('A',m.formationA);renderPitch('B',m.formationB);renderSummary();renderPool()}
function fillFormations(){const m=match();for(const t of ['A','B']){const el=$(`#formation${t}`);el.innerHTML=formations[m.format].map(f=>`<option ${f===m[`formation${t}`]?'selected':''}>${f}</option>`).join('')}}
function remapTeam(teamKey,newForm){const m=match(),old=Object.values(m[`team${teamKey}`]).filter(Boolean),newSlots=formationSlots(newForm),next={};for(const s of newSlots){let idx=old.findIndex(id=>player(id).pos===s.role||player(id).alt.split(',').map(x=>x.trim()).includes(s.role));if(idx<0)idx=0;if(old[idx])next[s.id]=old.splice(idx,1)[0]}m[`team${teamKey}`]=next;m.bench.push(...old)}
function changeFormat(n){const m=match(),old=m.format;m.format=Number(n);m.formationA=formations[n][0];m.formationB=formations[n][0];remapTeam('A',m.formationA);remapTeam('B',m.formationB);logEvent('formation',`Maç formatı ${n}'ye ${n} olarak değiştirildi`,`${old}'ya ${old} formatından geçildi`);renderSquad();notify('Format güncellendi; fazla oyuncular havuza döndü.')}
function compatibility(p,role){if(p.pos===role)return 3;if(p.alt.split(',').map(x=>x.trim()).includes(role))return 2;if(role==='OS'&&p.pos!=='KL')return 1;return 0}
function balanceTeams(){const m=match(),cap=m.format;const locked={A:{},B:{}};for(const t of ['A','B'])for(const [slot,id] of Object.entries(m[`team${t}`]))if(m.locked.includes(id))locked[t][slot]=id;const lockedIds=[...Object.values(locked.A),...Object.values(locked.B)];const eligible=[...new Set([...m.bench,...Object.values(m.teamA),...Object.values(m.teamB)])].filter(id=>!lockedIds.includes(id)).map(player).sort((a,b)=>overall(b)-overall(a));m.teamA={...locked.A};m.teamB={...locked.B};m.bench=[];
  const open={A:formationSlots(m.formationA).filter(s=>!m.teamA[s.id]),B:formationSlots(m.formationB).filter(s=>!m.teamB[s.id])};
  for(const t of ['A','B']){const g=open[t].find(s=>s.role==='KL');if(g){let i=eligible.findIndex(p=>p.pos==='KL');if(i>=0){m[`team${t}`][g.id]=eligible.splice(i,1)[0].id;open[t]=open[t].filter(s=>s!==g)}}}
  while(eligible.length&&(open.A.length||open.B.length)){const ma=teamMetrics(m.teamA),mb=teamMetrics(m.teamB);const target=(!open.A.length)?'B':(!open.B.length)?'A':ma.sum<=mb.sum?'A':'B';let slots=open[target];let best={score:-999,pi:0,si:0};for(let pi=0;pi<eligible.length;pi++)for(let si=0;si<slots.length;si++){const score=compatibility(eligible[pi],slots[si].role)*25-overall(eligible[pi])*.02;if(score>best.score)best={score,pi,si}}const p=eligible.splice(best.pi,1)[0],s=slots.splice(best.si,1)[0];m[`team${target}`][s.id]=p.id}
  let improved=true,rounds=0;while(improved&&rounds++<12){improved=false;let current=Math.abs(teamMetrics(m.teamA).sum-teamMetrics(m.teamB).sum),choice=null;for(const [sa,ia] of Object.entries(m.teamA))for(const [sb,ib] of Object.entries(m.teamB)){if(m.locked.includes(ia)||m.locked.includes(ib))continue;const ra=formationSlots(m.formationA).find(s=>s.id===sa)?.role,rb=formationSlots(m.formationB).find(s=>s.id===sb)?.role;if(!compatibility(player(ib),ra)||!compatibility(player(ia),rb))continue;const next=Math.abs((teamMetrics(m.teamA).sum-overall(player(ia))+overall(player(ib)))-(teamMetrics(m.teamB).sum-overall(player(ib))+overall(player(ia))));if(next<current){current=next;choice={sa,sb,ia,ib}}}if(choice){m.teamA[choice.sa]=choice.ib;m.teamB[choice.sb]=choice.ia;improved=true}}
  m.bench.push(...eligible.map(p=>p.id));const diff=Math.abs(teamMetrics(m.teamA).sum-teamMetrics(m.teamB).sum);logEvent('team','Dengeli takımlar oluşturuldu',`Güç farkı: ${diff} · Kilitli oyuncular korundu`);renderSquad();const missing=cap*2-(Object.keys(m.teamA).length+Object.keys(m.teamB).length);notify(missing>0?`Takımlar oluşturuldu. ${missing} oyuncu eksik.`:'Dengeli takımlar hazır! Kilitli oyuncular korundu.')}

function switchView(name){$$('.view').forEach(v=>v.classList.remove('active'));$(`#${name}View`).classList.add('active');$$('.nav-tab').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='players')renderPlayers();if(name==='matches')renderMatches();window.scrollTo({top:0,behavior:'smooth'})}
function renderPlayers(){const q=$('#playerSearch').value.toLocaleLowerCase('tr'),pos=$('#positionFilter').value,box=$('#playerGallery');box.innerHTML='';state.players.filter(p=>(p.name+' '+p.nick).toLocaleLowerCase('tr').includes(q)&&(pos==='all'||p.pos===pos)).sort((a,b)=>overall(b)-overall(a)).forEach(p=>{const tile=document.createElement('article');tile.className='player-tile';tile.append(playerCard(p));tile.insertAdjacentHTML('beforeend',`<h3>${p.name}</h3><p>${p.pos}${p.alt?' · Alternatif: '+p.alt:''}</p><button class="btn ghost">Kartı düzenle</button>`);tile.querySelector('.btn').onclick=()=>openPlayer(p.id);box.append(tile)})}
function makeStatControl(key,value){return `<label class="stat-control"><span>${statsMeta[key]}</span><input data-stat="${key}" type="range" min="1" max="99" value="${value}"><input data-number="${key}" type="number" min="1" max="99" value="${value}"></label>`}
function openPlayer(id=null){editingPlayer=id;const p=id?structuredClone(player(id)):{name:'',nick:'',pos:'OS',alt:'',stats:Object.fromEntries([...fieldKeys,...keeperKeys].map(k=>[k,70])),photo:avatar('Yeni Oyuncu','#779486'),photoX:50,photoY:50,photoScale:110};pendingPhoto=p.photo;$('#playerModalTitle').textContent=id?'Oyuncuyu düzenle':'Yeni oyuncu';$('#pName').value=p.name;$('#pNick').value=p.nick;$('#pPosition').value=p.pos;$('#pAlt').value=p.alt;$('#photoX').value=p.photoX||50;$('#photoY').value=p.photoY||50;$('#photoScale').value=p.photoScale||110;$('#fieldStats').innerHTML=fieldKeys.map(k=>makeStatControl(k,p.stats[k])).join('');$('#keeperStats').innerHTML=keeperKeys.map(k=>makeStatControl(k,p.stats[k])).join('');$('#deletePlayerBtn').style.visibility=id?'visible':'hidden';wireEditor();updatePreview();$('#playerDialog').showModal()}
async function optimizePhoto(file){
  const bitmap=await createImageBitmap(file),maxEdge=520,ratio=Math.min(1,maxEdge/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.8));if(!blob)throw new Error('image_encode_failed');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})
}
function draftPlayer(){const stats={};[...fieldKeys,...keeperKeys].forEach(k=>stats[k]=Number($(`[data-number="${k}"]`).value));return{id:editingPlayer||'preview',name:$('#pName').value||'Yeni Oyuncu',nick:$('#pNick').value||'YENİ',pos:$('#pPosition').value,alt:$('#pAlt').value,stats,photo:pendingPhoto,photoX:Number($('#photoX').value),photoY:Number($('#photoY').value),photoScale:Number($('#photoScale').value)}}
function wireEditor(){$$('#playerForm input,#playerForm select').forEach(el=>el.oninput=()=>{if(el.dataset.stat){$(`[data-number="${el.dataset.stat}"]`).value=el.value}if(el.dataset.number){el.value=Math.max(1,Math.min(99,Number(el.value)||1));$(`[data-stat="${el.dataset.number}"]`).value=el.value}updatePreview()})}
function updatePreview(){const p=draftPlayer();$('#cardPreview').innerHTML='';$('#cardPreview').append(playerCard(p));$('#liveOverall').textContent=overall(p);$('#keeperBlock').style.display=p.pos==='KL'?'block':'none';$('#formulaText').textContent=p.pos==='KL'?'%32 refleks · %28 kurtarış · %22 pozisyon · %18 dağıtma':p.pos==='DF'?'Defans %30 · fizik %22 · hız %13 ağırlıklı':p.pos==='OS'?'Pas %27 · stamina %20 · dripling %16 ağırlıklı':'Şut %30 · hız %20 · dripling %15 ağırlıklı'}
function deletePlayer(){if(!editingPlayer)return;if(!confirm('Bu oyuncuyu ve tüm kadro yerleşimlerini silmek istediğinize emin misiniz?'))return;const deleted=player(editingPlayer);state.players=state.players.filter(p=>p.id!==editingPlayer);state.matches.forEach(m=>{m.bench=m.bench.filter(x=>x!==editingPlayer);m.out=m.out.filter(x=>x!==editingPlayer);m.locked=m.locked.filter(x=>x!==editingPlayer);for(const t of ['A','B'])for(const [s,id] of Object.entries(m[`team${t}`]))if(id===editingPlayer)delete m[`team${t}`][s]});logEvent('player',`${deleted.nick} oyuncu listesinden silindi`,deleted.name);$('#playerDialog').close();renderPlayers();notify('Oyuncu silindi.')}
function renderMatches(){const box=$('#matchesList');box.innerHTML='';[...state.matches].sort((a,b)=>b.date.localeCompare(a.date)).forEach(m=>{const d=new Date(m.date+'T12:00:00'),a=teamMetrics(m.teamA),b=teamMetrics(m.teamB);const row=document.createElement('article');row.className='match-row';row.innerHTML=`<div class="match-date"><b>${d.getDate()}</b><small>${d.toLocaleDateString('tr-TR',{month:'short'}).toUpperCase()}</small></div><div><h3>${m.name}</h3><p>${m.format}'ya ${m.format} · A: ${Object.keys(m.teamA).length} oyuncu · B: ${Object.keys(m.teamB).length} oyuncu</p></div><div class="match-score"><div><b>${a.sum}</b><small>A GÜCÜ</small></div><div><b>${b.sum}</b><small>B GÜCÜ</small></div></div><div class="match-row-actions"><button class="btn ghost open">Aç</button><button class="btn ghost clone">Kopyala</button></div>`;row.querySelector('.open').onclick=()=>{state.activeMatchId=m.id;save();switchView('squad');renderSquad()};row.querySelector('.clone').onclick=()=>cloneMatch(m);box.append(row)})}
function openMatchDialog(isNew){const m=match();$('#matchModalTitle').textContent=isNew?'Yeni hafta':'Maç bilgilerini düzenle';$('#matchForm').dataset.new=isNew?'1':'0';$('#mName').value=isNew?'Halı Saha Maçı':m.name;$('#mDate').value=isNew?new Date(Date.now()+7*864e5).toISOString().slice(0,10):m.date;$('#matchDialog').showModal()}
function cloneMatch(src){const c=structuredClone(src);c.id=crypto.randomUUID();c.name=src.name+' · Yeni hafta';c.date=new Date(Date.now()+7*864e5).toISOString().slice(0,10);c.teamA={};c.teamB={};c.locked=[];c.bench=state.players.filter(p=>!c.out.includes(p.id)).map(p=>p.id);state.matches.push(c);state.activeMatchId=c.id;logEvent('match','Maç yeni haftaya kopyalandı',`${src.name} → ${c.name}`);switchView('squad');renderSquad();notify('Yeni hafta oluşturuldu.')}

$$('.nav-tab').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#homeBtn').onclick=()=>switchView('squad');$('#balanceBtn').onclick=balanceTeams;$('#formatSelect').onchange=e=>changeFormat(e.target.value);for(const t of ['A','B'])$(`#formation${t}`).onchange=e=>{const m=match(),old=m[`formation${t}`];remapTeam(t,e.target.value);m[`formation${t}`]=e.target.value;logEvent('formation',`Takım ${t} dizilişi değiştirildi`,`${old} → ${e.target.value}`);renderSquad()};
$('#poolTabs').onclick=e=>{const b=e.target.closest('button');if(b){state.poolTab=b.dataset.pool;save();renderPool()}};wireDrop($('#poolDrop'),id=>moveToZone(id,$('#poolDrop').dataset.zone));$('#poolDrop').addEventListener('click',e=>{if(!e.target.closest('.mini-card')&&selectedPlayer){moveToZone(selectedPlayer,$('#poolDrop').dataset.zone);selectedPlayer=null}});
$('#addPlayerBtn').onclick=()=>openPlayer();$('#playerSearch').oninput=renderPlayers;$('#positionFilter').onchange=renderPlayers;$('#newMatchBtn').onclick=()=>openMatchDialog(true);$('#newMatchBtn2').onclick=()=>openMatchDialog(true);$('#editMatchBtn').onclick=()=>openMatchDialog(false);
$('#photoInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>8*1024*1024){notify('Fotoğraf 8 MB’dan küçük olmalı.');return}try{pendingPhoto=await optimizePhoto(f);updatePreview();notify('Fotoğraf ortak kayıt için optimize edildi.')}catch(error){console.error(error);notify('Fotoğraf işlenemedi. JPG veya PNG deneyin.')}};
$('#playerForm').addEventListener('submit',e=>{e.preventDefault();const p=draftPlayer();if(!$('#pName').value.trim()||!$('#pNick').value.trim())return; if(editingPlayer){const before=overall(player(editingPlayer));Object.assign(player(editingPlayer),p,{id:editingPlayer});logEvent('player',`${p.nick} oyuncu kartı güncellendi`,`${p.pos} · Overall ${before} → ${overall(p)}`)}else{p.id=crypto.randomUUID();state.players.push(p);state.matches.forEach(m=>m.out.push(p.id));logEvent('player',`${p.nick} oyuncu listesine eklendi`,`${p.name} · ${p.pos} · ${overall(p)} overall`)}$('#playerDialog').close();renderPlayers();renderSquad();notify(editingPlayer?'Oyuncu kartı güncellendi.':'Yeni oyuncu kadro dışına eklendi.')});$('#deletePlayerBtn').onclick=deletePlayer;
$('#matchForm').addEventListener('submit',e=>{e.preventDefault();if(e.submitter?.value==='cancel')return;const isNew=e.currentTarget.dataset.new==='1';if(isNew){const m={id:crypto.randomUUID(),name:$('#mName').value,date:$('#mDate').value,format:6,formationA:'2-2-1',formationB:'2-2-1',bench:state.players.map(p=>p.id),out:[],teamA:{},teamB:{},locked:[]};state.matches.push(m);state.activeMatchId=m.id;logEvent('match','Yeni maç oluşturuldu',`${m.name} · ${formatDate(m.date)}`)}else{const old=match().name;match().name=$('#mName').value;match().date=$('#mDate').value;logEvent('match','Maç bilgileri güncellendi',`${old} → ${match().name}`)}$('#matchDialog').close();switchView('squad');renderSquad();notify('Maç kaydedildi.')});
$('#activityBtn').onclick=()=>{renderHistory();$('#activityDialog').showModal()};$('#closeActivityBtn').onclick=()=>$('#activityDialog').close();$('#activityDialog').addEventListener('click',e=>{if(e.target===$('#activityDialog'))$('#activityDialog').close()});$('#clearActivityBtn').onclick=()=>{if(confirm('İşlem geçmişi temizlensin mi?')){state.history=[];save();renderHistory();notify('İşlem geçmişi temizlendi.')}};
document.addEventListener('keydown',e=>{if(e.key==='Escape')selectedPlayer=null});
renderSquad();renderHistory();initSharedState();
